contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 value) public payable {
        require(true);

        address self = address(this);
        uint256 beforeSelf = c.balanceOf(self);
        uint256 beforeOwner = c.balanceOf(c.owner());
        uint256 beforeSupply = c.totalSupply();

        bool reverted;
        try c.burn(value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 afterSelf = c.balanceOf(self);
            uint256 afterOwner = c.balanceOf(c.owner());
            uint256 afterSupply = c.totalSupply();

            uint256 unaffected;
            if (self == c.owner()) {
                unaffected = beforeSupply - afterSupply;
            } else {
                unaffected = beforeSelf - afterSelf;
            }

            assert(unaffected == 0 && afterOwner == beforeOwner);
        } else {
            assert(c.balanceOf(self) == beforeSelf);
        }
    }

    receive() external payable {}
}

