contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _to, uint256 _value) public payable {
        require(_to != address(0), "recipient must not be zero address");

        uint256 senderBalanceBefore = c.balanceOf(address(this));
        uint256 recipientBalanceBefore = c.balanceOf(_to);
        uint256 totalSupplyBefore = c.totalSupply();

        bool reverted;
        bool success;
        try c.transfer(_to, _value) returns (bool s) {
            reverted = false;
            success = s;
        } catch {
            reverted = true;
        }

        uint256 senderBalanceAfter = c.balanceOf(address(this));
        uint256 recipientBalanceAfter = c.balanceOf(_to);
        uint256 totalSupplyAfter = c.totalSupply();

        if (!reverted) {
            assert(
                success == true &&
                senderBalanceAfter == senderBalanceBefore - _value &&
                recipientBalanceAfter == recipientBalanceBefore + _value &&
                totalSupplyAfter == totalSupplyBefore
            );
        }
    }
}

